Boolean  pipe_insert ( Pipe pipe  , Pipe_Data data , TskTimeout timeout )
{    
    UInt8 i ; 
    
    Pipe_Node *node = (Pipe_Node*)q_remove( pipe->q_free , timeout);
    
    if(node)
    {
        memcpy( node->data , data , pipe->element_size );

        q_insert( pipe->q_pennding , (Q_Msg*)node ); 
    }
    
    return !!(node) ; 
}         

